```python
def factor_system_poly(polys, **kwargs):
    if not polys:
        return [[]]

    if not all(isinstance(poly, Poly) for poly in polys):
        raise TypeError("polys should be a list of Poly instances")

    # Get base generators and check compatibility
    base_gens = polys[0].gens
    for poly in polys[1:]:
        if not set(poly.gens).issubset(base_gens):
            missing_gens = set(poly.gens) - set(base_gens)
            raise DomainError(f"Incompatible generators: {missing_gens} not found in first polynomial")

    # Get the most general domain among all polynomials
    base_domain = polys[0].domain
    for poly in polys[1:]:
        try:
            # Attempt to unify domains
            base_domain = base_domain.unify(poly.domain)
        except Exception:
            raise DomainError(f"Incompatible domains: cannot unify {base_domain} with {poly.domain}")

    # Convert all polynomials to the unified domain
    unified_polys = []
    for i, poly in enumerate(polys):
        try:
            # Convert polynomial to unified domain while preserving gens order
            unified_poly = Poly(poly.as_expr(), *base_gens, domain=base_domain)
            unified_polys.append(unified_poly)
        except Exception as e:
            raise DomainError(f"Failed to convert polynomial {i} to unified domain: {e}")

    # Replace original polys with unified versions
    polys = unified_polys

    if any(poly.total_degree() == 0 and not poly.is_zero for poly in polys):
        return []

    factored_eqs = []
    for poly in polys:
        constant, factors = poly.factor_list()

        if constant.is_zero and not factors:
            continue

        current_factors = []
        if factors:
            if constant.is_number and constant != 0:
                current_factors.extend((Poly(factor, *base_gens, domain=base_domain), [])
                                    for factor, _ in factors)
            else:
                current_factors.extend((Poly(factor, *base_gens, domain=base_domain),
                                     [Poly(constant, *base_gens, domain=base_domain)])
                                    for factor, _ in factors)
        elif not constant.is_zero:
            return []

        if current_factors:
            factored_eqs.append(current_factors)

    if not factored_eqs:
        return [[]]

    return _combine_factor_systems_poly(factored_eqs)
```

Something like the following should work:

```python 
def _process_system_equations(eqs, gens=None, **kwargs):
    """ Helper function to process system equations and convert to polynomials. """
    
    if not eqs
        return None, []

    exprs = [sympify(eq) for eq in eqs]
    exprs = [expr.simplify() for expr in exprs]

    if all(expr.is_zero for expr in exprs):
        return None, [[]]

    exprs = [expr for expr in exprs if not expr.is_zero]

    if not exprs:
        return None, [[]]

    if not gens:
        try:
            # Let SymPy try to figure out the generators
            polys, opt = parallel_poly_from_expr(exprs, **kwargs)
            gens = opt.gens
        except (GeneratorsNeeded, PolificationFailed):
            # If that fails, check if I was dealing with constants this whole time
            if all(expr.free_symbols == set() for expr in exprs):
                if any(not expr.is_zero for expr in exprs):
                    return None, []
                return None, [[]]
            raise ValueError("Could not determine generators. Please specify them explicitly.")

    # Now we have gens finally, so try polyfication
    try:
        polys, _ = parallel_poly_from_expr(exprs, gens, **kwargs)
    except PolificationFailed as e:
        if all(expr.free_symbols == set() for expr in exprs):
            if any(not expr.is_zero for expr in exprs):
                return None, []
            return None, [[]]
        raise ValueError("The input expressions could not be converted to polynomials.")

    if not polys:
        return None, []

    if any(poly.total_degree() == 0 and not poly.is_zero for poly in polys):
        return None, []

    return polys, None


def factor_system_cond(eqs, gens=None, **kwargs):

    polys, result = _process_system_equations(eqs, gens, **kwargs)
    if result is not None:
        return result

    poly_results = factor_system_poly(polys, **kwargs)

    results = []
    for combo in poly_results:
        factor_conditions = {}
        for factor, conditions in combo:
            expr = factor.as_expr()
            if expr not in factor_conditions:
                factor_conditions[expr] = []
            factor_conditions[expr].extend(conditions)

        boolean_combo = []
        for factor, conditions in factor_conditions.items():
            if not conditions:
                boolean_combo.append((factor, sympy.true))
            else:
                bool_cond = Or(*[Ne(cond.as_expr(), 0) for cond in conditions])
                boolean_combo.append((factor, bool_cond))

        results.append(boolean_combo)

    return results


def factor_system(eqs, gens=None, **kwargs):

    polys, result = _process_system_equations(eqs, gens, **kwargs)
    if result is not None:
        return result

    poly_results = factor_system_poly(polys, **kwargs)
    return [{factor.as_expr() for factor, _ in combo} for combo in poly_results]
```    

I have standardized the return of `[[]]` in both functions when the system of equations comprises solely of zeroes to indicate infinite solutions.

