Consistent check for `False` instead of `None` resolves the issue. 

```python
    if n < 0:
        if candidates is None:
            pp = perfect_power(-n, big=True, factor=factor)
            if not pp:
                return False

            b, e = pp
            e2 = e & (-e)
            b, e = b ** e2, e // e2

            if e <= 1:
                return False

            if big or isprime(e):
                return -b, e

            for p in primerange(3, e + 1):
                if e % p == 0:
                    return -b ** (e // p), p

        odd_candidates = {i for i in candidates if i % 2}
        if not odd_candidates:
            return False
        pp = perfect_power(-n, odd_candidates, big, factor)
        if pp:
            return -pp[0], pp[1]
        return False

    if isinstance(n, Rational) and not isinstance(n, Integer):
        p, q = n.p, n.q
        
        if p == 1:
            qq = perfect_power(q, candidates, big, factor)
            return (S.One / qq[0], qq[1]) if qq else False
        
        pp = perfect_power(p)
        if not pp:
            return False
        
        qq = perfect_power(q)
        if not qq:
            return False
        
        num_base, num_exp = pp
        den_base, den_exp = qq

        def compute_tuple(exponent):
            """Helper to compute final result given an exponent"""
            new_num = num_base ** (num_exp // exponent)
            new_den = den_base ** (den_exp // exponent)
            return n.func(new_num, new_den), exponent

        if candidates:
            valid_candidates = [i for i in candidates
                                if num_exp % i == 0 and den_exp % i == 0]
            if not valid_candidates:
                return False
            e = max(valid_candidates) if big else min(valid_candidates)
            return compute_tuple(e)
        
        g = math.gcd(num_exp, den_exp)
        if g == 1:
            return False
        if big:
            return compute_tuple(g)
        e = next(p for p in primerange(2, g + 1) if g % p == 0)
        return compute_tuple(e)    
``` 

But this has other issues even though it now also handles negative rational numbers. See [here](https://github.com/sympy/sympy/pull/27239#discussion_r1837024901  ).  

**Edit: This is handled in the prev comment, the page didn't refresh for me so couldn't see it earlier.**

if not all(nd := (perfect_power(i, factor=factor) for i in (p, q))):
    return False
(num_base, num_exp), (den_base, den_exp) = nd

