```python
In [5]: sols = solve(groebner(eqs, s), s, dict=True)

In [6]: for s in sols: print(s)
{a4: 2*a1**2 + a2**2/2, a5: -a3**2}
{a1: 0, a2: 0, a5: -a3**2 - a4**2/4}
{a2: 0, a4: 2*a1**2, a5: -a3**2}
